<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Shortage Statement</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <h3 class="text-center text-uppercase">GOODS RECEIVED NOTES SHORTAGE STATEMENT</h3>

    <div class="d-flex me-4 mt-2">
      <div class="ms-auto">
        <button class="btn btn-success" @click="printShortageStatement()">
          <i class="bi bi-printer fs-5"></i>
        </button>
      </div>
    </div>

    <!-- loading spinner starts -->
    <div v-if="loading_spinner" v-html="tableShimmer()"></div>
    <!-- Loading spinner ends -->

    <div v-else class="row layout-top-spacing">
      <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table :data="notes" :columns="columns" :options="table_option">
              <template #beforeFilter>
                <div class="custom-dropdown dropdown btn-group">
                  <a
                    class="btn dropdown-toggle btn-icon-only"
                    href="#"
                    role="button"
                    id="showColumns"
                    data-bs-toggle="dropdown"
                    aria-haspopup="true"
                    aria-expanded="false"
                  >
                    <button
                      aria-haspopup="true"
                      aria-expanded="false"
                      type="button"
                      class="btn dropdown-toggle btn-outline-primary"
                    >
                      Show Columns
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="24"
                        height="24"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        stroke-width="2"
                        stroke-linecap="round"
                        stroke-linejoin="round"
                        class="feather feather-chevron-down"
                      >
                        <polyline points="6 9 12 15 18 9"></polyline>
                      </svg>
                    </button>
                  </a>

                  <div
                    class="dropdown-menu dropdown-menu-end"
                    @click="$event.stopPropagation()"
                  >
                    <div
                      class="checkbox-outline-primary mx-3 my-2 custom-control custom-checkbox"
                      v-for="(column, index) in columns"
                      :key="index"
                    >
                      <input
                        variant="primary"
                        type="checkbox"
                        class="custom-control-input"
                        :checked="
                          table_option.hiddenColumns.includes(column) ? false : true
                        "
                        :id="'chk' + index"
                        @change="show_hide_columns(column, $event.target.checked)"
                      />
                      <label class="custom-control-label" :for="'chk' + index">
                        {{ capitalize(column) }}
                      </label>
                    </div>
                  </div>
                </div>
              </template>
              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.color"
                  >{{ props.row.status.name }}
                </span>
              </template>
              <template #actions="props">
                <a
                  v-if="user_permissions.includes('can_edit_shortage_statement')"
                  href="javascript:;"
                  class="edit me-3"
                  @click="openEditModal(props.row)"
                  data-bs-toggle="modal"
                  data-bs-target="#edit-statement-modal"
                >
                  <i class="bi bi-pencil-square fs-4 text-primary"/>
                </a>

                <a
                  href="javascript:void(0);"
                  class="text-secondary position-relative me-2"
                  @click="
                    openEditModal(props.row);
                    noteModalRef.open(null, props.row.id);
                  "
                >
                  <i class="bi bi-journal-bookmark-fill fs-5"></i>
                  <span
                    v-if="props.row.logs_count > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.logs_count }}
                  </span>
                </a>
              </template>
              <template #lpo="props">
                <router-link
                  :to="`/approval-chain/${props.row.lpo}`"
                  class="badge bg-primary"
                  >{{ props.row.lpo }}</router-link
                >
              </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>

    <!-- Edit Shortage Statement modal starts -->
    <div
      class="modal fade mymodal"
      id="edit-statement-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="editStatementModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="editStatementModalLabel">
              Edit Shortage Statement
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="closeEditModal()"
            ></button>
          </div>
          <form @submit.prevent="updateStatement()">
            <div class="modal-body">
              <div class="row mb-3">
                <div class="col-md-6">
                  <label for="status">Status</label>
                  <Multiselect
                    v-model="status"
                    :options="statuses"
                    label="name"
                    placeholder="Select Status"
                    :searchable="true"
                    :allow-empty="false"
                  />
                </div>
                <div class="col-md-6">
                  <label for="quantity">Quantity</label>
                  <input
                    type="number"
                    v-model="quantity"
                    class="form-control"
                    placeholder="Enter Quantity"
                    step="0.01"
                  />
                </div>
                <div class="col-md-12">
                  <label for="briefing">briefing</label>
                  <input
                    type="text"
                    v-model="briefing"
                    class="form-control"
                    placeholder="Enter Briefing"
                  />
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button
                type="button"
                class="btn btn-secondary"
                data-bs-dismiss="modal"
                @click="closeEditModal()"
                id="close_editing"
              >
                Close
              </button>
              <button type="submit" class="btn btn-primary">
                <span
                  v-if="loading_spinner"
                  class="spinner-border spinner-border-sm text-white me-2"
                  role="status"
                ></span>
                Edit
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
    <!-- Edit Shortage Statement modal ends -->

      <NoteModal
      ref="noteModalRef"
      :source-id="grn_id"
      source="SHORTAGE_STATEMENT"
      module="SHORTAGE STATEMENTS"
      title="Shortage Statement"
      @logs-updated="(count) => (issue.logs_count = count)"
    />
  

  </div>
</template>

<script setup>
import { onMounted, ref, inject, watch } from "vue";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";
useMeta({ title: "Good Issue Note" });
import NoteModal from "@/components/reusables/NoteModal.vue";
const noteModalRef = ref(null);

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const formatDate = inject("formatDate");
const formatNumber = inject("formatNumber");
const tableShimmer = inject("tableShimmer");
const briefing = ref("");
const quantity = ref("");
const status = ref(null);

const loading_spinner = ref(false);
const columns = ref(["SNo", "grn", "lpo", "date", "project", "item", "description", "receiver", "approved", "received", "shortage", "units", "briefing", "remark", "cost", "actions"]);
const notes = ref([]);
const items = ref([]);
const table_option = ref({
  perPage: 20,
  perPageValues: [20, 50, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo", "name", "short_name", "status"],
  sortIcon: {
    base: "sort-icon-none",
    up: "sort-icon-asc",
    down: "sort-icon-desc",
  },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: true,
  hiddenColumns: ["briefing", "remark", "description",'approved'],
});

const loading = ref(false);

const issue = ref("");

const getShortageStatement = () => {
  loading_spinner.value = true;
  axiosInstance
    .get("/copex/report/stores/shortage-grn")
    .then((response) => {
      notes.value = response.data.map((item, index) => {
        return {
          ...item,
          SNo: index + 1,
          id: item.id,
          logs_count: item.logs_count,
          receiver: item?.receiver?.name,
          grn: item.grn_id,
          lpo: item.approval_item.approval_list_id,
          project: item.grn.approval.requisition.project?.short_name,
          remark: item.remark,
          date: formatDate(item.created_at),
          item:
            item.approval_item.requisition_item.remark ||
            item.approval_item.requisition_item.description,
          description: item.approval_item.requisition_item.description,
          units: item.approval_item.requisition_item.units,
          rate: item.approval_item.requisition_item.rate,
          received: item.quantity,
          approved: item.approval_item.quantity,
          shortage: (item.approval_item.quantity - item.quantity).toFixed(2),
          briefing: item.description,
          cost: formatNumber(
            item.approval_item.requisition_item.rate *
              (item.approval_item.quantity - item.quantity)
          ),
          rate: item.approval_item.requisition_item.rate,
        };
      });

      loading_spinner.value = false;
    })
    .catch((error) => {
      showError(error.message || "Failed to fetch units");
      loading_spinner.value = false;
    });
};

const statuses = ref([]);
const getStatuses = async () => {
  const response = await axiosInstance.get("statuses");
  statuses.value = response.data;
};

const capitalize = (text) => {
  return text
    .replace("_", " ")
    .replace("-", " ")
    .toLowerCase()
    .split(" ")
    .map((s) => s.charAt(0).toUpperCase() + s.substring(1))
    .join(" ");
};

const show_hide_columns = (column, value) => {
  if (!table_option.value.hiddenColumns.includes(column) && !value) {
    table_option.value.hiddenColumns.push(column);
  } else {
    table_option.value.hiddenColumns = table_option.value.hiddenColumns.filter(
      (d) => d !== column
    );
  }
};

const openEditModal = (row) => {
  issue.value = row;
  briefing.value = row.briefing || "";
  quantity.value = row.quantity || 0;
  status.value = statuses.value.find((s) => s.id === row.status_id) || null;
};

const updateStatement = async () => {
  loading_spinner.value = true;
  const row = issue.value;
  const payload = {
    description: briefing.value,
    status_id: status.value.id,
    quantity: quantity.value,
  };

  try {
    const response = await axiosInstance.put(`grn-items/${row.id}`, payload);
    showMessage("Statement updated successfully");
    document.getElementById("close_editing").click();
    getShortageStatement();
  } catch (error) {
    console.error("Error updating GRN item:", error);
    showError(error.response?.data?.message || "Failed to update statement");
  } finally {
    loading_spinner.value = false;
  }
};

const closeEditModal = () => {
  briefing.value = "";
  quantity.value = "";
  status.value = null;
};

const showMessage = inject("showMessage");
const showError = inject("showError");

const printShortageStatement = () => {
  try {
    const rows = notes.value;

    const allColumns = [
      { key: "SNo", label: "No.", render: (row, i) => i + 1 },
      { key: "grn", label: "GRN", render: (row) => row.grn || "--" },
      { key: "lpo", label: "LPO", render: (row) => row.lpo || "--" },
      { key: "date", label: "Date", render: (row) => row.date || "--" },
      { key: "project", label: "Project", render: (row) => row.project || "--" },
      { key: "item", label: "Item", render: (row) => row.item || "--" },
      {
        key: "description",
        label: "Description",
        render: (row) => row.description || "--",
      },
      { key: "receiver", label: "Receiver", render: (row) => row.receiver || "--" },
      { key: "approved", label: "Approved", render: (row) => row.approved || "0" },
      { key: "received", label: "Received", render: (row) => row.received || "0" },
      { key: "shortage", label: "Shortage", render: (row) => row.shortage || "0" },
      { key: "units", label: "Units", render: (row) => row.units || "--" },
      { key: "briefing", label: "Briefing", render: (row) => row.briefing || "--" },
      { key: "remark", label: "Remark", render: (row) => row.remark || "--" },
      { key: "cost", label: "Cost", render: (row) => row.cost || "0" },
    ];

    const visibleColumns = allColumns.filter(
      (col) => !table_option.value.hiddenColumns.includes(col.key)
    );

    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>GRN Shortage Statement</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 12px; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 17px; margin: 10px 0; font-weight: bold; }
  table { width: 100%; border-collapse: collapse; margin-top: 6px; }
  th, td { border: 0.5px solid #000; padding: 5px; }
  th { background-color: #f8f8f8; font-weight: bold; text-align: center; }
  .text-center { text-align: center; }
  .text-right { text-align: right; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0; }
  @page { size: A4 landscape; margin: 10mm; }
  @media print { body { margin: 0; } }
</style>
</head>
<body>

<div class="company-title">
  <i>
    <h1>COPEX CONTRACTORS CO. LTD</h1>
    <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
    <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
    <div><b>Email:</b> info@copexcontractors.co.tz</div>
    <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">
<div class="title">GOODS RECEIVED NOTES SHORTAGE STATEMENT</div>
<hr>

<table>
  <thead>
    <tr>
      ${visibleColumns.map((col) => `<th>${col.label}</th>`).join("")}
    </tr>
  </thead>
  <tbody>
    ${
      rows.length > 0
        ? rows
            .map(
              (row, index) => `
    <tr>
      ${visibleColumns.map((col) => `<td>${col.render(row, index)}</td>`).join("")}
    </tr>`
            )
            .join("")
        : `<tr><td colspan="${visibleColumns.length}" class="text-center">No records found</td></tr>`
    }
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => document.body.removeChild(iframe), 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};

onMounted(() => {
  getShortageStatement();
  getStatuses();
});
</script>
